begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(14);
select is((select count(*)::int from pg_tables where schemaname='public' and rowsecurity and tablename in ('payments','payment_allocations')),2,'Payment tables enforce RLS');
select ok(not has_table_privilege('authenticated','public.payments','select'),'Raw payment numeric data is hidden');
create temporary table payment_scope(label text primary key,id uuid);grant select,insert on payment_scope to authenticated;
insert into auth.users(id,email) values('99999100-0000-0000-0000-000000000001','native-payments@example.test');
set local role authenticated;set local request.jwt.claim.sub='99999100-0000-0000-0000-000000000001';
insert into payment_scope select 'tenant',public.create_business('Native Payments');
insert into payment_scope select 'branch',id from public.branches limit 1;
insert into payment_scope select 'customer',public.save_customer((select id from payment_scope where label='tenant'),null,'{"first_name":"Native payer","phone":"998901234"}',array[(select id from payment_scope where label='branch')]);
insert into payment_scope select 'cashbox',public.save_cashbox((select id from payment_scope where label='tenant'),null,gen_random_uuid(),jsonb_build_object('name','Payment drawer','cashbox_type','cash','branch_id',(select id from payment_scope where label='branch')));
insert into payment_scope select 'invoice',public.save_invoice_draft((select id from payment_scope where label='tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',(select id from payment_scope where label='branch'),'customer_id',(select id from payment_scope where label='customer'),'issue_date',current_date,'due_date',current_date,'discount_amount','0'),'[{"description":"Tuition","quantity":"1","unit_price":"100","discount_amount":"0"}]');
select public.transition_invoice((select id from payment_scope where label='tenant'),(select id from payment_scope where label='invoice'),gen_random_uuid(),1,'issue');
insert into payment_scope select 'payment',public.post_payment((select id from payment_scope where label='tenant'),'99999100-0000-0000-0000-000000000010',jsonb_build_object('branch_id',(select id from payment_scope where label='branch'),'customer_id',(select id from payment_scope where label='customer'),'cashbox_id',(select id from payment_scope where label='cashbox'),'amount','100.10','method','cash','paid_at','2026-10-22T12:00:00+05:00'),jsonb_build_array(jsonb_build_object('invoice_id',(select id from payment_scope where label='invoice'),'amount','40.00')));
set constraints all immediate;
select is(public.cashbox_details((select id from payment_scope where label='tenant'),(select id from payment_scope where label='cashbox'))->>'balance','100.10','Payment posts exact cash once');
select is(public.invoice_details((select id from payment_scope where label='tenant'),(select id from payment_scope where label='invoice'))->>'outstanding','60.00','Partial allocation reduces debt');
select is(public.payment_details((select id from payment_scope where label='tenant'),(select id from payment_scope where label='payment'))->'payment'->>'credit','60.10','Unused payment remains credit');
select is(public.post_payment((select id from payment_scope where label='tenant'),'99999100-0000-0000-0000-000000000010',jsonb_build_object('branch_id',(select id from payment_scope where label='branch'),'customer_id',(select id from payment_scope where label='customer'),'cashbox_id',(select id from payment_scope where label='cashbox'),'amount','100.10','method','cash','paid_at','2026-10-22T12:00:00+05:00'),jsonb_build_array(jsonb_build_object('invoice_id',(select id from payment_scope where label='invoice'),'amount','40.00'))),(select id from payment_scope where label='payment'),'Duplicate request returns original payment');
select is(public.cashbox_details((select id from payment_scope where label='tenant'),(select id from payment_scope where label='cashbox'))->>'balance','100.10','Retry does not post cash again');
select throws_ok($$select public.allocate_payment((select id from payment_scope where label='tenant'),(select id from payment_scope where label='payment'),(select id from payment_scope where label='invoice'),gen_random_uuid(),'61')$$,'P0001','Allocation exceeds payment credit or invoice balance','Over-allocation rejected');
set constraints all deferred;
select lives_ok($$select public.allocate_payment((select id from payment_scope where label='tenant'),(select id from payment_scope where label='payment'),(select id from payment_scope where label='invoice'),gen_random_uuid(),'60')$$,'Remaining debt may be settled');
set constraints all immediate;
select is(public.invoice_details((select id from payment_scope where label='tenant'),(select id from payment_scope where label='invoice'))->>'status','paid','Paid status is derived');
select is(public.payment_details((select id from payment_scope where label='tenant'),(select id from payment_scope where label='payment'))->'payment'->>'credit','0.10','Exact residual credit remains');
select is(public.cashbox_details((select id from payment_scope where label='tenant'),(select id from payment_scope where label='cashbox'))->>'balance','100.10','Later allocation never changes cash');
reset role;
select throws_ok($$delete from public.payments where id=(select id from payment_scope where label='payment')$$,'23514','Posted financial history is immutable','Posted payment cannot be deleted');
set local role authenticated;set local request.jwt.claim.sub='';
select throws_ok($$select public.payment_details((select id from payment_scope where label='tenant'),(select id from payment_scope where label='payment'))$$,'42501','Payment access denied','Subjectless clients cannot read payment');
reset role;select * from finish();rollback;
